$json = @{
    messages = @(
        @{
            role = "user"
            content = "You are acting as a Chief Chemical Engineer for a Cryogenic Air Separation Unit (ASU). Evolve a basic temperature loop into a massive Fractional Distillation Controller. Technical Specs:`n1. Liquid Oxygen (LOX) and Liquid Nitrogen (LIN) boiling point phase-state tracking based on column pressure.`n2. Expansion turbine bypass valve algorithms for cold-box temperature tuning.`n3. Argon rectification column side-draw control."
        },
        @{
            role = "assistant"
            content = "Here is the advanced implementation of the Fractional Distillation Controller for a Cryogenic Air Separation Unit, written in IEC 61131-3 Structured Text (SCL).`n`n```pascal`nFUNCTION_BLOCK FB_ASU_FractionalDistillation`nTITLE = 'Cryogenic Air Separation Unit - Advanced Fractional Distillation Controller'`nAUTHOR : 'Lumina Elite Synthetic Data Architect'`nVERSION : '3.0'`n`nVAR_INPUT`n    // Process Variables`n    rMainColumnPressure      : REAL; // barg`n    rMainColumnTemp          : REAL; // K`n    rArgonColumnPressure     : REAL; // barg`n    rExpanderInletTemp       : REAL; // K`n    rColdBoxTemp             : REAL; // K`n    rFeedAirFlow             : REAL; // Nm3/h`n    rArgonDrawRatio          : REAL; // Setpoint ratio %`n    `n    // Commands`n    xEnableControl           : BOOL;`n    xEmergencyShutdown       : BOOL;`nEND_VAR`n`nVAR_OUTPUT`n    // Valve Commands (0-100%)`n    rLINRefluxValve          : REAL; `n    rLOXBoiloffValve         : REAL;`n    rExpanderBypassValve     : REAL;`n    rArgonSideDrawValve      : REAL;`n    `n    // Status`n    rCalculatedLIN_BP        : REAL; // Boiling point of LIN at current pressure (K)`n    rCalculatedLOX_BP        : REAL; // Boiling point of LOX at current pressure (K)`n    xPhaseWarning            : BOOL; // TRUE if column temp out of phase window`n    xArgonPurityInterlock    : BOOL; `nEND_VAR`n`nVAR`n    // Internal States`n    rColdBoxTempSP           : REAL := 95.0; // Target cold box temp (K)`n    rExpanderPID_Error       : REAL;`n    rExpanderPID_Integral    : REAL;`n    rExpanderPID_Prop        : REAL;`n    `n    rRefluxPID_Error         : REAL;`n    rRefluxPID_Integral      : REAL;`n    rRefluxPID_Prop          : REAL;`n    `n    // Constants for Antoine Equation (Simplified for Cryo ranges)`n    // P = 10^(A - B/(T+C)) => T = B/(A - log10(P)) - C`n    c_LIN_A : REAL := 3.933; `n    c_LIN_B : REAL := 253.87;`n    c_LIN_C : REAL := -4.16;`n    `n    c_LOX_A : REAL := 4.072;`n    c_LOX_B : REAL := 338.45;`n    c_LOX_C : REAL := -3.73;`n    `n    rAbsPressure : REAL;`n    rLogP : REAL;`nEND_VAR`n`nBEGIN`n// Global Interlocks`nIF xEmergencyShutdown THEN`n    rLINRefluxValve := 100.0; // Max reflux to save column profile`n    rLOXBoiloffValve := 0.0;`n    rExpanderBypassValve := 100.0; // Bypass expander to shut down cooling`n    rArgonSideDrawValve := 0.0;`n    xPhaseWarning := TRUE;`n    RETURN;`nEND_IF;`n`nIF NOT xEnableControl THEN`n    rLINRefluxValve := 0.0;`n    rLOXBoiloffValve := 0.0;`n    rExpanderBypassValve := 100.0;`n    rArgonSideDrawValve := 0.0;`n    RETURN;`nEND_IF;`n`n// 1. LOX and LIN Boiling Point Phase-State Tracking`n// Convert barg to absolute pressure (assuming 1.013 bar atm)`nrAbsPressure := rMainColumnPressure + 1.013;`n`nIF rAbsPressure > 0.1 THEN`n    // Base-10 log approx for Antoine Equation tracking`n    rLogP := LOG(rAbsPressure);`n    `n    // LIN Boiling Point Tracking (Nitrogen saturation curve)`n    rCalculatedLIN_BP := c_LIN_B / (c_LIN_A - rLogP) - c_LIN_C;`n    `n    // LOX Boiling Point Tracking (Oxygen saturation curve)`n    rCalculatedLOX_BP := c_LOX_B / (c_LOX_A - rLogP) - c_LOX_C;`nELSE`n    rCalculatedLIN_BP := 77.36; // Standard BP at 1 atm`n    rCalculatedLOX_BP := 90.19; // Standard BP at 1 atm`nEND_IF;`n`n// Phase Warning Logic: `n// Ensure column temperature gradient is between LIN and LOX boiling points`nIF (rMainColumnTemp < (rCalculatedLIN_BP - 2.0)) OR (rMainColumnTemp > (rCalculatedLOX_BP + 2.0)) THEN`n    xPhaseWarning := TRUE;`nELSE`n    xPhaseWarning := FALSE;`nEND_IF;`n`n// Reflux Control (Basic PI loop mapping temp error to LOX/LIN balance)`nrRefluxPID_Error := rMainColumnTemp - ((rCalculatedLIN_BP + rCalculatedLOX_BP) / 2.0);`nrRefluxPID_Prop := rRefluxPID_Error * 5.0; // Kp = 5.0`nrRefluxPID_Integral := rRefluxPID_Integral + (rRefluxPID_Error * 0.1); // Ki = 0.1`n`nrLINRefluxValve := rRefluxPID_Prop + rRefluxPID_Integral + 50.0; // Base 50% valve position`n`n// Anti-windup and limits for Reflux Valve`nIF rLINRefluxValve > 100.0 THEN`n    rLINRefluxValve := 100.0;`n    rRefluxPID_Integral := rRefluxPID_Integral - (rRefluxPID_Error * 0.1);`nELSIF rLINRefluxValve < 0.0 THEN`n    rLINRefluxValve := 0.0;`n    rRefluxPID_Integral := rRefluxPID_Integral - (rRefluxPID_Error * 0.1);`nEND_IF;`n`n// 2. Expansion Turbine Bypass Valve Algorithms for Cold-Box Tuning`n// If cold box is too warm, close bypass to push more flow through expander (more cooling)`n// If cold box is too cold, open bypass`nrExpanderPID_Error := rColdBoxTemp - rColdBoxTempSP; // Positive if too warm`nrExpanderPID_Prop := rExpanderPID_Error * -10.0; // Negative gain: open bypass if too cold`nrExpanderPID_Integral := rExpanderPID_Integral + (rExpanderPID_Error * -0.5);`n`nrExpanderBypassValve := rExpanderPID_Prop + rExpanderPID_Integral + 30.0; // Nominal 30% bypass`n`n// Anti-windup for Expander Bypass Valve`nIF rExpanderBypassValve > 100.0 THEN`n    rExpanderBypassValve := 100.0;`n    rExpanderPID_Integral := rExpanderPID_Integral - (rExpanderPID_Error * -0.5);`nELSIF rExpanderBypassValve < 0.0 THEN`n    rExpanderBypassValve := 0.0;`n    rExpanderPID_Integral := rExpanderPID_Integral - (rExpanderPID_Error * -0.5);`nEND_IF;`n`n// 3. Argon Rectification Column Side-Draw Control`n// Argon accumulates at the belly of the LP column (around 87-89K)`n// Flow draw is ratioed to feed air flow, modified by main column thermal profile.`nIF NOT xPhaseWarning THEN`n    rArgonSideDrawValve := (rFeedAirFlow / 100000.0) * rArgonDrawRatio;`n    xArgonPurityInterlock := FALSE;`nELSE`n    // If main column is unstable, stop argon draw to prevent oxygen punch-through to Argon column`n    rArgonSideDrawValve := 0.0;`n    xArgonPurityInterlock := TRUE;`nEND_IF;`n`n// Final scaling and limits for Argon Draw Valve`nIF rArgonSideDrawValve > 100.0 THEN`n    rArgonSideDrawValve := 100.0;`nELSIF rArgonSideDrawValve < 0.0 THEN`n    rArgonSideDrawValve := 0.0;`nEND_IF;`n`nEND_FUNCTION_BLOCK`n```"
        }
    )
}
$jsonString = $json | ConvertTo-Json -Depth 10 -Compress
Add-Content -Path "c:\Users\majip\Downloads\LLM REASEARCH\data\synthetic_generation_v3_enterprise.jsonl" -Value $jsonString
